// Vendored-package drift gate (architecture.md §12 п. 2, HB-005, HK-033).
// vendor/ is generated by the hub's scripts/vendor-sdk.mjs and
// scripts/vendor-hotkeys.mjs and never hand-edited: any byte change, or a
// re-vendor without updating tests/vendor-pins.json, turns this red.

import { createHash } from 'node:crypto';
import { readdirSync, readFileSync, statSync } from 'node:fs';
import { join, relative } from 'node:path';
import { fileURLToPath } from 'node:url';

import { HOTKEY_SCHEME_VERSION, HOTKEYS } from '@chatgoose/hotkeys';
import { KERNEL_CONTRACT_HASH, KERNEL_SDK_VERSION, createClient, kernelOperations } from '@kernel/sdk';
import { describe, expect, it } from 'vitest';

import pins from './vendor-pins.json' with { type: 'json' };

const repoRoot = fileURLToPath(new URL('..', import.meta.url));
const sdkDir = join(repoRoot, 'vendor/kernel-sdk');
const hotkeysDir = join(repoRoot, 'vendor/chatgoose-hotkeys');

function sha256(data: string | Buffer): string {
  return createHash('sha256').update(data).digest('hex');
}

function listFiles(dir: string): string[] {
  return readdirSync(dir).flatMap((name) => {
    const path = join(dir, name);
    return statSync(path).isDirectory() ? listFiles(path) : [path];
  });
}

/** Same scheme as vendor-hotkeys.mjs: sha256 of the JSON map {relative path: sha256}. */
function treeSha256(root: string): string {
  const files: Record<string, string> = {};
  for (const path of listFiles(join(root, 'dist')).sort()) files[relative(root, path)] = sha256(readFileSync(path));
  return sha256(JSON.stringify(files));
}

const readJson = (path: string): Record<string, unknown> => JSON.parse(readFileSync(path, 'utf8')) as Record<string, unknown>;

describe('vendored @kernel/sdk', () => {
  const manifest = readJson(join(sdkDir, 'kernel-sdk.vendor.json'));

  it('matches the pinned prod contract hash and source commit', () => {
    expect(KERNEL_CONTRACT_HASH).toMatch(/^[0-9a-f]{64}$/);
    expect(manifest['contractHash']).toBe(KERNEL_CONTRACT_HASH);
    expect(manifest['contractHash']).toBe(pins.kernelSdk.contractHash);
    expect(manifest['sourceCommit']).toBe(pins.kernelSdk.sourceCommit);
    expect(manifest['sourceCommit']).toMatch(/^[0-9a-f]{40}$/);
  });

  it('is byte-identical to what the hub script generated', () => {
    expect(treeSha256(sdkDir)).toBe(pins.kernelSdk.distSha256);
  });

  it('loads at runtime and exposes the operations', () => {
    expect(KERNEL_SDK_VERSION).toBeTruthy();
    const client = createClient({ baseUrl: 'http://127.0.0.1:0', auth: { mode: 'bearer', token: () => 'k' } });
    expect(typeof client).toBe('object');
    expect(Object.keys(kernelOperations).length).toBeGreaterThan(100);
  });
});

describe('vendored @chatgoose/hotkeys', () => {
  const manifest = readJson(join(hotkeysDir, 'chatgoose-hotkeys.vendor.json'));
  const files = manifest['files'] as Record<string, string>;

  it('[HK-033] matches its manifest file by file', () => {
    for (const [file, hash] of Object.entries(files)) {
      expect(sha256(readFileSync(join(hotkeysDir, file))), file).toBe(hash);
    }
    expect(sha256(JSON.stringify(files))).toBe(manifest['sha256']);
    expect(treeSha256(hotkeysDir)).toBe(manifest['sha256']);
  });

  it('carries the same scheme bytes as the Fansly extension and the desktop', () => {
    expect(manifest['sha256']).toBe(pins.chatgooseHotkeys.sha256);
    expect(manifest['sourceCommit']).toBe(pins.chatgooseHotkeys.sourceCommit);
  });

  it('loads at runtime', () => {
    expect(manifest['schemeVersion']).toBe(HOTKEY_SCHEME_VERSION);
    expect(HOTKEYS.length).toBeGreaterThan(0);
  });
});
